// Derives the missing "passing" walk pose of a side-view supporter atlas from its single authored stride pose, so
// Tower Defense levels whose fans only had one walking frame (Los Redondos ID10) alternate their legs while walking:
// pose 0 = authored stride (legs apart), pose 1 = passing pose (legs swung under the hips), like La Renga.
// Nothing is generated by an AI service: every pixel comes from the original atlas ("paper doll" animation).
//
// Per cell: the transparent gap between the two legs is tracked upward from the soles to its apex (the crotch);
// the pixels below the hip pivot are split into back leg (left of the gap) and front leg (right of it). Each leg
// is rotated rigidly about the hip pivot (thigh, trousers and shoe keep their drawing) toward vertical, the back leg
// drawn first and the front leg over it; the rotated legs are lifted back to the original sole line. Head, torso,
// arms and the hands beside the hips stay identical; small detached specks left under the hips are removed.
//
// Usage: swift tools/art/make_walk_poses_from_stride.swift <stride.png> <columns> <rows> <passing-out.png> [swing] [pivot-above-crotch]
import Foundation
import CoreGraphics
import ImageIO

let args = CommandLine.arguments
guard args.count >= 5, let columns = Int(args[2]), let rows = Int(args[3]) else {
    fatalError("usage: make_walk_poses_from_stride.swift <stride.png> <columns> <rows> <passing-out.png> [swing] [pivot-above-crotch]")
}
// 1 = both legs swing all the way to vertical (feet together under the hips); 2 would mirror the stride.
// The default 0.85 leaves the feet slightly apart, which reads best and leaves the fewest seams.
let swing = args.count > 5 ? Double(args[5])! : 0.85
// Hip pivot height above the crotch, as a share of the visible inseam (crotch to sole).
let pivotAboveCrotch = args.count > 6 ? Double(args[6])! : 0.55
let space = CGColorSpaceCreateDeviceRGB()

func loadImage(_ path: String) -> CGImage {
    let src = CGImageSourceCreateWithURL(URL(fileURLWithPath: path) as CFURL, nil)!
    return CGImageSourceCreateImageAtIndex(src, 0, nil)!
}

let sheet = loadImage(args[1])
let W = sheet.width, H = sheet.height
var source = [UInt8](repeating: 0, count: W * H * 4)
do {
    let ctx = CGContext(data: &source, width: W, height: H, bitsPerComponent: 8, bytesPerRow: W * 4, space: space,
                        bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)!
    ctx.draw(sheet, in: CGRect(x: 0, y: 0, width: W, height: H))
}
// Buffer row 0 is the top of the image (CGBitmapContext memory is top-down).
@inline(__always) func alpha(_ x: Int, _ y: Int) -> UInt8 { source[(y * W + x) * 4 + 3] }
let opaque: UInt8 = 48

struct Run { var start: Int; var end: Int }  // [start, end)
func runs(row y: Int, from x0: Int, to x1: Int) -> [Run] {
    var result: [Run] = []
    var x = x0
    while x < x1 {
        while x < x1 && alpha(x, y) < opaque { x += 1 }
        if x >= x1 { break }
        let s = x
        while x < x1 && alpha(x, y) >= opaque { x += 1 }
        if x - s >= 2 { result.append(Run(start: s, end: x)) }
    }
    return result
}

struct Leg { var isBack: Bool; var angle: Double }

struct CellGeometry {
    var x0 = 0, x1 = 0, y0 = 0, y1 = 0
    var sole = 0, apexY = 0, pivotX = 0.0, pivotY = 0.0, contentBottom = 0
    var gapMid: [Int: Double] = [:]        // rows from apexY to sole
    var backFoot = 0.0, frontFoot = 0.0    // foot centroid x on the lowest band
    var hipLeft = 0, hipRight = 0          // trouser extent at the crotch row; hands beside the hips stay put

    /// Pixels that belong to the legs: everything under the crotch, and the hip band between the hip extents.
    func isLeg(_ x: Int, _ y: Int) -> Bool { y > apexY || (x >= hipLeft && x < hipRight) }
    var valid = false

    /// True when the source pixel belongs to the back (left) leg; only meaningful below the pivot.
    func isBack(_ x: Int, _ y: Int) -> Bool {
        if y <= apexY { return Double(x) < pivotX }
        return Double(x) < (gapMid[y] ?? gapMid[apexY]!)
    }
}

func analyse(column: Int, row: Int) -> CellGeometry {
    var g = CellGeometry()
    g.x0 = Int((Double(column) * Double(W) / Double(columns)).rounded(.down))
    g.x1 = Int((Double(column + 1) * Double(W) / Double(columns)).rounded(.down))
    g.y0 = Int((Double(row) * Double(H) / Double(rows)).rounded(.down))
    g.y1 = Int((Double(row + 1) * Double(H) / Double(rows)).rounded(.down))
    // The feet may hang a few pixels past the nominal cell edge (and the next row's hair may reach up to them):
    // the cell's content ends at the first empty row around the edge or, when the two touch, at the thinnest one.
    let lo = g.y1 - (g.y1 - g.y0) / 8, hi = min(H, g.y1 + (g.y1 - g.y0) / 10)
    var boundary = hi, thinnest = Int.max
    for y in lo..<hi {
        let width = runs(row: y, from: g.x0, to: g.x1).reduce(0) { $0 + $1.end - $1.start }
        if width == 0 { boundary = y; break }
        if width < thinnest { thinnest = width; boundary = y }
    }
    var sole = -1
    for y in ((g.y0 + g.y1) / 2)..<boundary { if runs(row: y, from: g.x0, to: g.x1).isEmpty { break }; sole = y }
    g.contentBottom = boundary - 1
    guard sole > 0 else { return g }
    g.sole = sole
    // Seed: the row of the feet/shins band with the widest interior gap (the gap between the legs); then track
    // that gap upward while it stays connected, up to its apex (the crotch).
    func widestGap(_ y: Int) -> (Int, Int)? {
        let r = runs(row: y, from: g.x0, to: g.x1)
        guard r.count >= 2 else { return nil }
        var best: (Int, Int)? = nil
        for i in 0..<(r.count - 1) where best == nil || r[i + 1].start - r[i].end > best!.1 - best!.0 { best = (r[i].end, r[i + 1].start) }
        return best
    }
    var gap: (Int, Int)? = nil
    var seed = sole
    for yy in (sole - (g.y1 - g.y0) / 6)...sole {
        if let w = widestGap(yy), gap == nil || w.1 - w.0 > gap!.1 - gap!.0 { gap = w; seed = yy }
    }
    if let w = gap { g.gapMid[seed] = Double(w.0 + w.1) / 2 }
    var y = seed - 1
    let limit = g.y0 + (g.y1 - g.y0) / 2
    guard var current = gap else { return g }
    var apex = seed
    while y > limit {
        let r = runs(row: y, from: g.x0, to: g.x1)
        var next: (Int, Int)? = nil
        if r.count >= 2 {
            for i in 0..<(r.count - 1) {
                let a = r[i].end, b = r[i + 1].start
                if a < current.1 && b > current.0 { next = (a, b); break }  // overlaps the gap below
            }
        }
        guard let n = next else { break }
        current = n
        g.gapMid[y] = Double(n.0 + n.1) / 2
        apex = y
        y -= 1
    }
    // Follow the same gap down to the soles; rows where it closes (a toe over a heel) keep the last split.
    if let seedGap = gap, seed < sole {
        var below = seedGap
        for yy in (seed + 1)...sole {
            let r = runs(row: yy, from: g.x0, to: g.x1)
            guard r.count >= 2 else { continue }
            for i in 0..<(r.count - 1) where r[i].end < below.1 && r[i + 1].start > below.0 {
                below = (r[i].end, r[i + 1].start); g.gapMid[yy] = Double(below.0 + below.1) / 2; break
            }
        }
    }
    // Rows under the first two-feet row (a foot lower than the other) keep the lowest measured split.
    var last = g.gapMid[apex]!
    for yy in apex...sole { if let m = g.gapMid[yy] { last = m } else { g.gapMid[yy] = last } }
    g.apexY = apex
    let legLength = Double(sole - apex)
    guard legLength >= 18 else { return g }
    // Hip pivot: above the crotch by about half the visible inseam, centred on the crotch.
    g.pivotX = g.gapMid[apex]!
    let apexRuns = runs(row: apex, from: g.x0, to: g.x1)
    let mid = Int(g.pivotX)
    g.hipLeft = apexRuns.last(where: { $0.end <= mid + 1 })?.start ?? g.x0
    g.hipRight = apexRuns.first(where: { $0.start >= mid - 1 })?.end ?? g.x1
    g.pivotY = Double(apex) - legLength * pivotAboveCrotch
    // Foot centroids on the lowest fifth.
    var l = 0.0, ln = 0.0, rr = 0.0, rn = 0.0
    for yy in (sole - Int(legLength * 0.3))...sole {
        for x in g.x0..<g.x1 where alpha(x, yy) >= opaque {
            if Double(x) < g.gapMid[yy]! { l += Double(x); ln += 1 } else { rr += Double(x); rn += 1 }
        }
    }
    guard ln > 0 && rn > 0 else { return g }
    g.backFoot = l / ln; g.frontFoot = rr / rn
    g.valid = true
    return g
}

@inline(__always) func sample(_ x: Double, _ y: Double) -> (Double, Double, Double, Double) {
    // Bilinear sample of the premultiplied source.
    let fx = floor(x), fy = floor(y)
    let ix = Int(fx), iy = Int(fy)
    let ax = x - fx, ay = y - fy
    var acc = (0.0, 0.0, 0.0, 0.0)
    for (dx, dy, w) in [(0, 0, (1 - ax) * (1 - ay)), (1, 0, ax * (1 - ay)), (0, 1, (1 - ax) * ay), (1, 1, ax * ay)] {
        let sx = ix + dx, sy = iy + dy
        if sx < 0 || sy < 0 || sx >= W || sy >= H || w == 0 { continue }
        let i = (sy * W + sx) * 4
        acc.0 += Double(source[i]) * w; acc.1 += Double(source[i + 1]) * w
        acc.2 += Double(source[i + 2]) * w; acc.3 += Double(source[i + 3]) * w
    }
    return acc
}

func makePose(swing: Double) -> [UInt8] {
    var out = source
    for row in 0..<rows {
        for column in 0..<columns {
            let g = analyse(column: column, row: row)
            if !g.valid { FileHandle.standardError.write("cell \(column),\(row): no legs found, kept\n".data(using: .utf8)!); continue }
            let footY = Double(g.sole) - Double(g.sole - g.apexY) * 0.15
            let backAngle = atan2(g.backFoot - g.pivotX, footY - g.pivotY)    // negative: behind the hip
            let frontAngle = atan2(g.frontFoot - g.pivotX, footY - g.pivotY)  // positive: ahead of the hip
            // Rotation (radians, counter-clockwise on screen = foot moves right) applied to each leg.
            let backTurn = -swing * backAngle
            let frontTurn = -swing * frontAngle
            let top = Int(g.pivotY.rounded(.up))
            // Lift so the lowest rotated sole lands on the original sole line.
            func lift(_ turn: Double, _ angle: Double) -> Double {
                let reach = Double(g.sole) - g.pivotY
                let len = reach / max(0.2, cos(angle))
                return len * cos(angle + turn) - reach
            }
            let raise = max(0, max(lift(backTurn, backAngle), lift(frontTurn, frontAngle)))
            // Clear everything below the hip pivot (including faint shadow rows under the soles); the rotated legs
            // start at the pivot, where their displacement is zero, so they join the untouched torso without a seam.
            for yy in top...g.contentBottom {
                for x in g.x0..<g.x1 where g.isLeg(x, yy) { let di = (yy * W + x) * 4; for c in 0..<4 { out[di + c] = 0 } }
            }
            for leg in [Leg(isBack: true, angle: backTurn), Leg(isBack: false, angle: frontTurn)] {
                let c = cos(leg.angle), s = sin(leg.angle)
                for yy in top...g.contentBottom {
                    for x in g.x0..<g.x1 {
                        // Inverse rotation: destination -> source (screen y grows downward).
                        let dx = Double(x) - g.pivotX, dy = Double(yy) + raise - g.pivotY
                        let sx = g.pivotX + c * dx - s * dy
                        let sy = g.pivotY + s * dx + c * dy
                        let ix = Int(sx.rounded()), iy = Int(sy.rounded())
                        if iy <= top || iy > g.sole || ix < g.x0 || ix >= g.x1 || !g.isLeg(ix, iy) { continue }
                        if g.isBack(ix, iy) != leg.isBack { continue }
                        let p = sample(sx, sy)
                        let a = p.3
                        if a < 1 { continue }
                        let di = (yy * W + x) * 4
                        let inv = 1 - a / 255
                        out[di] = UInt8(min(255, p.0 + Double(out[di]) * inv))
                        out[di + 1] = UInt8(min(255, p.1 + Double(out[di + 1]) * inv))
                        out[di + 2] = UInt8(min(255, p.2 + Double(out[di + 2]) * inv))
                        out[di + 3] = UInt8(min(255, a + Double(out[di + 3]) * inv))
                    }
                }
            }
            removeSpecks(&out, g, maxPixels: 400)
        }
    }
    return out
}

/// Removes small specks (pieces of one leg's outline that followed the other leg) left under the hips.
func removeSpecks(_ out: inout [UInt8], _ g: CellGeometry, maxPixels: Int) {
    let top = Int(g.pivotY.rounded(.up)), bottom = g.contentBottom
    let w = g.x1 - g.x0, h = bottom - top + 1
    var label = [Int](repeating: -1, count: w * h)
    for sy in 0..<h { for sx in 0..<w where label[sy * w + sx] < 0 && out[((sy + top) * W + sx + g.x0) * 4 + 3] > 0 {
        var stack = [(sx, sy)], members: [(Int, Int)] = [], touchesTop = false
        label[sy * w + sx] = 1
        while let (cx, cy) = stack.popLast() {
            members.append((cx, cy)); if cy == 0 { touchesTop = true }
            for dy in -1...1 { for dx in -1...1 {
                let nx = cx + dx, ny = cy + dy
                if nx < 0 || ny < 0 || nx >= w || ny >= h || label[ny * w + nx] >= 0 { continue }
                if out[((ny + top) * W + nx + g.x0) * 4 + 3] == 0 { continue }
                label[ny * w + nx] = 1; stack.append((nx, ny))
            } }
        }
        if !touchesTop && members.count <= maxPixels {
            for (mx, my) in members { let di = ((my + top) * W + mx + g.x0) * 4; for c in 0..<4 { out[di + c] = 0 } }
        }
    } }
}

func save(_ pixels: [UInt8], _ path: String) {
    var data = pixels
    let ctx = CGContext(data: &data, width: W, height: H, bitsPerComponent: 8, bytesPerRow: W * 4, space: space,
                        bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)!
    let image = ctx.makeImage()!
    let dest = CGImageDestinationCreateWithURL(URL(fileURLWithPath: path) as CFURL, "public.png" as CFString, 1, nil)!
    CGImageDestinationAddImage(dest, image, nil)
    guard CGImageDestinationFinalize(dest) else { fatalError("cannot write \(path)") }
}

for row in 0..<rows { for column in 0..<columns {
    let g = analyse(column: column, row: row)
    print("cell \(column),\(row): sole \(g.sole - g.y0) apex \(g.apexY - g.y0) pivot \(Int(g.pivotX) - g.x0),\(Int(g.pivotY) - g.y0) feet \(Int(g.backFoot) - g.x0)/\(Int(g.frontFoot) - g.x0) valid \(g.valid)")
} }
save(makePose(swing: swing), args[4])
print("wrote \(args[4]) (\(W)x\(H), \(columns)x\(rows) cells, swing \(swing))")
